func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request) {
	creds, err := parseCreds(r)
	if err != nil {
		s.log.Error("login failed",
			"error", err,
			"email", creds.Email,
			"password", creds.Password,
		)
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	s.log.Debug("attempting login",
		"email", creds.Email,
		"store_stats", s.users.Stats(), // walks the whole user cache
	)

	if err := s.auth.Verify(r.Context(), creds); err != nil {
		s.log.Error("login failed", "error", err, "email", creds.Email)
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}
